// Command netplay-identity computes a simulation identity and writes it as a
// Go file. Run it with go generate from the simulation's package:
//
//	//go:generate go run m31labs.dev/gosx/netplay/cmd/netplay-identity -src step.go,state.go -data moves.json -det v1.2.0
//
// The generated file defines SimulationIdentity, the value to put in
// netplay.Config.Identity, and SimulationGoVersion.
package main

import (
	"flag"
	"fmt"
	"go/format"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"m31labs.dev/gosx/netplay"
)

func main() {
	if err := run(os.Args[1:], os.Stderr); err != nil {
		fmt.Fprintln(os.Stderr, "netplay-identity:", err)
		os.Exit(1)
	}
}

func run(args []string, log io.Writer) error {
	fs := flag.NewFlagSet("netplay-identity", flag.ContinueOnError)
	fs.SetOutput(log)
	pkg := fs.String("pkg", os.Getenv("GOPACKAGE"), "package name of the generated file (default $GOPACKAGE)")
	out := fs.String("o", "identity_gen.go", "output file")
	src := fs.String("src", "", "comma-separated simulation source files")
	data := fs.String("data", "", "comma-separated data files (moves, frame data, roster)")
	det := fs.String("det", "", "version of the det toolkit, if the simulation uses it")
	goVer := fs.String("go", runtime.Version(), "Go toolchain version to record")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *pkg == "" {
		return fmt.Errorf("-pkg is required when GOPACKAGE is not set")
	}
	if *src == "" {
		return fmt.Errorf("-src is required: list the simulation source files")
	}
	read := func(list string) ([]netplay.IdentityFile, error) {
		var files []netplay.IdentityFile
		for _, p := range strings.Split(list, ",") {
			if p = strings.TrimSpace(p); p == "" {
				continue
			}
			b, err := os.ReadFile(p)
			if err != nil {
				return nil, err
			}
			files = append(files, netplay.IdentityFile{Name: filepath.ToSlash(filepath.Clean(p)), Data: b})
		}
		return files, nil
	}
	sources, err := read(*src)
	if err != nil {
		return err
	}
	datas, err := read(*data)
	if err != nil {
		return err
	}
	id, err := netplay.ComputeIdentity(*goVer, *det, sources, datas)
	if err != nil {
		return err
	}
	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by netplay-identity; DO NOT EDIT.\n\npackage %s\n\n", *pkg)
	b.WriteString("// SimulationIdentity hashes the simulation's sources, data files, Go version\n// and det version. Put it in netplay.Config.Identity.\n")
	b.WriteString("var SimulationIdentity = [32]byte{")
	for i, c := range id {
		if i%8 == 0 {
			b.WriteString("\n\t")
		} else {
			b.WriteString(" ")
		}
		fmt.Fprintf(&b, "0x%02x,", c)
	}
	b.WriteString("\n}\n\n")
	fmt.Fprintf(&b, "// SimulationGoVersion is the Go version recorded in SimulationIdentity.\nconst SimulationGoVersion = %q\n", *goVer)
	if *det != "" {
		fmt.Fprintf(&b, "\n// SimulationDetVersion is the det version recorded in SimulationIdentity.\nconst SimulationDetVersion = %q\n", *det)
	}
	formatted, err := format.Source([]byte(b.String()))
	if err != nil {
		return err
	}
	return os.WriteFile(*out, formatted, 0o644)
}
